<?php
declare(strict_types=1);if(PHP_SAPI!=='cli'){http_response_code(404);exit;}require dirname(__DIR__).'/app/Core/bootstrap.php';
use App\Core\{Database,Encryption,CronLock};use App\Services\PlatformSetting;
if(!CronLock::acquire('health_alerts')){echo"Monitor já em execução.\n";exit;}$pdo=Database::connection();$email=trim((string)PlatformSetting::get('cron.alert_email',''));$phone=preg_replace('/\D/','',(string)PlatformSetting::get('cron.alert_whatsapp',''));$cooldown=max(15,min(1440,(int)PlatformSetting::get('cron.alert_cooldown','120')));if(!filter_var($email,FILTER_VALIDATE_EMAIL))$email='';if(!preg_match('/^\d{10,15}$/',$phone))$phone='';if($email===''&&$phone===''){echo"Alertas não configurados.\n";exit;}
$limits=['worker'=>10,'appointment_reminders'=>20,'automation_dispatch'=>20,'arena'=>20,'barber'=>20,'auto'=>20,'incident_monitor'=>20,'memberships'=>1500,'subscription_notifications'=>1500,'privacy_retention'=>1500,'backup'=>1500];$alerts=0;
foreach($limits as $key=>$limit){$q=$pdo->prepare('SELECT * FROM cron_heartbeats WHERE cron_key=:k ORDER BY started_at DESC,id DESC LIMIT 1');$q->execute(['k'=>$key]);$last=$q->fetch();$age=$last?(int)floor((time()-strtotime((string)($last['finished_at']?:$last['started_at'])))/60):999999;$failed=!$last||$last['status']==='failed'||($last['status']==='running'&&$age>30)||$age>$limit;$state=$failed?'failed':'ok';$alertKey=$key.':'.$state;$recent=$pdo->prepare('SELECT 1 FROM cron_alert_log WHERE alert_key=:k AND created_at>=DATE_SUB(NOW(),INTERVAL :m MINUTE) LIMIT 1');$recent->bindValue(':k',$alertKey);$recent->bindValue(':m',$cooldown,\PDO::PARAM_INT);$recent->execute();if($recent->fetchColumn())continue;$hadFailure=$pdo->prepare("SELECT 1 FROM cron_alert_log WHERE alert_key=:k AND status='sent' ORDER BY id DESC LIMIT 1");$hadFailure->execute(['k'=>$key.':failed']);if(!$failed&&!$hadFailure->fetchColumn())continue;$message=$failed?"ApPlanner: o cron {$key} está com falha ou atraso. Última execução: ".($last['started_at']??'nunca').". Estado: ".($last['status']??'sem registro').". Verifique: php tools/applanner-cron-health.php --strict":"ApPlanner: o cron {$key} voltou ao normal em ".($last['finished_at']??$last['started_at']);foreach(array_filter(['email'=>$email,'whatsapp'=>$phone]) as $channel=>$destination){try{$payload=Encryption::encrypt(['channel'=>$channel,'destination'=>$destination,'subject'=>$failed?'Falha em cron do ApPlanner':'Cron do ApPlanner recuperado','message'=>$message]);$pdo->prepare("INSERT INTO jobs(tenant_id,type,payload_encrypted,status,attempts,available_at,created_at,updated_at)VALUES(NULL,'campaign.send',:p,'queued',0,NOW(),NOW(),NOW())")->execute(['p'=>$payload]);$pdo->prepare("INSERT INTO cron_alert_log(alert_key,channel,status,message,created_at)VALUES(:k,:c,'sent',:m,NOW())")->execute(['k'=>$alertKey,'c'=>$channel,'m'=>$message]);$alerts++;}catch(Throwable $e){$pdo->prepare("INSERT INTO cron_alert_log(alert_key,channel,status,message,error_message,created_at)VALUES(:k,:c,'failed',:m,:e,NOW())")->execute(['k'=>$alertKey,'c'=>$channel,'m'=>$message,'e'=>mb_substr($e->getMessage(),0,500)]);}}}
echo"Alertas enfileirados: {$alerts}\n";
